cases.yaml:
schema: {deps: rests_on, snapshot: seen, predicate: wrong_if}
sources:
  s.note:
    name: 'מקור 日本語 <script> & #quot; [check] `text`'
    file: notes.md
    read: 2026-01-01
known:
  m.cost: {v: 12, from: s.note, name: Cost, metadata: {current: new}}
  m.other: {v: 3, unit: percent, from: 'a prose locator'}
  m.total: {rule: {expr: 'm.cost + m.other'}}
judgments:
  d.muted: {verdict: Continue, rests_on: [m.cost], seen: {m.cost: 10}, wrong_if: 'm.cost > 20'}
  d.falsified: {verdict: Stop, rests_on: [m.cost], seen: {m.cost: 10}, wrong_if: 'm.cost > 11'}
  d.moved: {verdict: Review, rests_on: [m.cost], seen: {m.cost: 10}, reopened_by: 'A new quote arrives'}
  d.blocked:
    verdict: Wait
    rests_on: [missing.entry]
    seen: {missing.entry: true}
    blocked_on: {missing: [missing.entry], why: 'Awaiting confirmation'}
findings:
  hyp.old: {v: refuted, refutes: [d.moved], at: 'Trial failed'}

